# Collect all output=4 and output=0 conditions side by side
def analyze_demos(demos, condition_name):
    all_pred_4 = []
    all_pred_0 = []
    for i in range(4):
        for j in range(4):
            pred = None  # will compute based on condition
            if condition_name == "pred_anti":
                pred = 4 if i % 2 == 1 else 0
            elif condition_name == "pred_col3":
                pred = 4 if 2*j+3 < 8 and demos[i][2*j+3] != 0 else 0
            else:
                pred = 0
            if pred == 4:
                all_pred_4.append((i, j, demos[i][2*j], demos[i][2*j+1]))
            else:
                all_pred_0.append((i, j, demos[i][2*j], demos[i][2*j+1]))
    return all_pred_4, all_pred_0

